// Normaliza los webhooks de coexistencia de Meta en listas para un solo INSERT.
const h = $json.headers || {};
if (h['x-cadabra-clave'] !== '1903d8e4b6a133f6486979d9999abc3ea13fc0404477a38e') return [];
const body = $json.body || {};
const out = { pnid: null, mensajes: [], pausar: [], contactos: [], baja_waba: null, baja_evento: null, nota: null };
const dig = (s) => String(s || '').replace(/\D/g, '');
const texto = (m) => m.text?.body ?? m.image?.caption ?? m.video?.caption ?? m.document?.caption ?? ('[' + (m.type || 'mensaje') + ']');
for (const e of body.entry || []) {
  for (const ch of e.changes || []) {
    const v = ch.value || {};
    out.pnid = out.pnid || v.metadata?.phone_number_id || null;
    if (ch.field === 'smb_message_echoes') {
      // El dueño escribió desde la app: se guarda como 'vendedor' y se pausa el bot en ese chat.
      for (const m of v.message_echoes || []) {
        const tel = dig(m.to);
        if (!tel) continue;
        out.mensajes.push({ tel, role: 'vendedor', texto: texto(m), mid: m.id || null, ts: Number(m.timestamp) || Date.now() / 1000, importado: false });
        if (!out.pausar.includes(tel)) out.pausar.push(tel);
      }
    } else if (ch.field === 'history') {
      for (const hb of v.history || []) {
        const md = hb.metadata || {};
        out.nota = `historial: fase ${md.phase ?? '?'} · parte ${md.chunk_order ?? '?'} · ${md.progress ?? '?'}%`;
        for (const t of hb.threads || []) {
          const contacto = dig(t.id);
          for (const m of t.messages || []) {
            const desde = dig(m.from);
            out.mensajes.push({ tel: contacto, role: desde === contacto ? 'user' : 'vendedor', texto: texto(m), mid: m.id || null, ts: Number(m.timestamp) || 0, importado: true });
          }
        }
      }
      for (const er of v.errors || []) out.nota = `historial no disponible: ${er.code} ${er.title || er.message || ''}`.trim();
    } else if (ch.field === 'smb_app_state_sync') {
      for (const s of v.state_sync || []) {
        if (s.type !== 'contact') continue;
        const tel = dig(s.contact?.phone_number);
        if (tel) out.contactos.push({ tel, nombre: s.contact?.full_name || s.contact?.first_name || null, accion: s.action === 'remove' ? 'remove' : 'add' });
      }
    } else if (ch.field === 'account_update') {
      if (['PARTNER_REMOVED', 'ACCOUNT_OFFBOARDED'].includes(v.event)) {
        out.baja_waba = String(v.waba_info?.waba_id || e.id || '');
        out.baja_evento = v.event;
      }
    }
  }
}
if (!out.mensajes.length && !out.contactos.length && !out.baja_waba && !out.nota) return [];
return [{ json: { datos: JSON.stringify(out) } }];
